<?php
$admin = (bool) auth_user()?->isAdmin();
$openTickets = (int) \App\Core\Database::scalar("SELECT COUNT(*) FROM Tickets WHERE Status = 'open'");
$serviceItems = $serviceCols = $productItems = $productCols = [];
$productCounts = array_count_values(array_map(static fn ($p): string => (string) $p->Dienstsoort, \App\Models\Product::where([])));
foreach (\App\Models\Product::SOORTEN as $col => $kinds) {
    $menuCol = ['Domeinen' => 'Domein & Hosting', 'Hosting' => 'Domein & Hosting', 'Development' => 'Development & Marketing', 'Marketing' => 'Development & Marketing'][$col] ?? $col;
    foreach ($kinds as $kind => [$kindIcon, $kindDesc]) {
        $serviceCols[$menuCol][] = count($serviceItems);
        $serviceItems[] = ['/beheer/diensten/' . \App\Models\Product::soortSlug($kind), $kindIcon, $kind, $kindDesc];
        $n = $productCounts[$kind] ?? 0;
        $productCols[$menuCol][] = count($productItems);
        $productItems[] = ['/beheer/producten/' . \App\Models\Product::soortSlug($kind, true), $kindIcon, $kind === 'Domeinnamen' ? 'Domeinextensies' : $kind, $n === 0 ? 'Nog geen producten' : $n . ($kind === 'Domeinnamen' ? ($n === 1 ? ' extensie' : ' extensies') : ($n === 1 ? ' product' : ' producten')) . ' te koop'];
    }
}
$pendingServices = (int) \App\Core\Database::scalar("SELECT COUNT(*) FROM Diensten WHERE Status = 'in_afwachting'");
$navSections = array_values(array_filter([
    ['key' => 'dashboard', 'label' => 'Dashboard', 'icon' => 'dashboard', 'items' => [['/beheer', 'dashboard', 'Overzicht']]],
    ['key' => 'klanten', 'label' => 'Klanten', 'icon' => 'users', 'count' => $openTickets, 'items' => [['/beheer/klanten', 'users', 'Klanten', 'Alle klanten en klantkaarten'], ['/beheer/crediteuren', 'building', 'Crediteuren', 'Leveranciers en hun gegevens'], ['/beheer/leads', 'target', 'Leads', 'Potentiële klanten opvolgen'], ['/beheer/projecten', 'layout', 'Projecten', 'Lopende en geplande projecten'], ['/beheer/afspraken', 'calendar', 'Afspraken', 'Agenda met klantafspraken'], ['/beheer/contracten', 'file', 'Contracten', 'SLA\'s, onderhoud en abonnementen'], ['/beheer/facturen', 'file', 'Facturen', 'Verkoopfacturen en betalingen'], ['/beheer/offertes', 'quote', 'Offertes', 'Offertes en akkoorden'], ['/beheer/inkoopfacturen', 'wallet', 'Inkoopfacturen', 'Facturen van leveranciers'], ['/beheer/btw', 'euro', 'BTW Overzicht', 'Btw-aangifte per kwartaal'], ['/beheer/tickets', 'ticket', 'Tickets', 'Vragen en storingen van klanten', $openTickets], ['/beheer/website/kennisbank', 'book', 'Kennisbank', 'Hulpartikelen voor klanten'], ['/beheer/storingen', 'zap', 'Storingen', 'Storingen en gepland onderhoud'], ['/beheer/snelle-antwoorden', 'chat', 'Snelle antwoorden', 'Standaardteksten voor tickets']], 'columns' => ['Relaties' => [0, 1, 2], 'Werk' => [3, 4, 5], 'Financieel' => [6, 7, 8, 9], 'Support' => [10, 11, 12, 13]], 'action' => ['/beheer/klanten/nieuw', 'Nieuwe klant'], 'also' => ['/beheer/documenten']],
    ['key' => 'diensten', 'label' => 'Diensten', 'icon' => 'server', 'href' => '/beheer/diensten', 'count' => $pendingServices, 'items' => $serviceItems, 'columns' => $serviceCols, 'also' => ['/beheer/diensten'], 'footer' => [['/beheer/diensten', 'server', 'Alle diensten'], ['/beheer/diensten?verloopt=30', 'calendar', 'Te factureren (30 dagen)'], ['/beheer/diensten?status=in_afwachting', 'clock', 'In afwachting' . ($pendingServices > 0 ? ' (' . $pendingServices . ')' : '')]], 'action' => ['/beheer/diensten/nieuw', 'Nieuwe dienst']],
    ['key' => 'producten', 'label' => 'Producten', 'icon' => 'box', 'href' => '/beheer/producten', 'items' => $productItems, 'columns' => $productCols, 'also' => ['/beheer/producten'], 'footer' => [['/beheer/producten', 'box', 'Alle producten'], ['/beheer/producten/domeinextensies', 'globe', 'Domeinextensies']], 'action' => ['/beheer/producten/nieuw', 'Nieuw product']],
    $admin ? ['key' => 'platform', 'label' => 'Instellingen', 'icon' => 'settings', 'items' => [['/beheer/instellingen#bedrijf', 'building', 'Bedrijfsgegevens', 'Naam, adres, KvK, btw en bank'], ['/beheer/instellingen#branding', 'image', 'Branding', 'Logo, favicon en kleuren'], ['/beheer/instellingen#website', 'globe', 'Website', 'Topbar, homepage en footer'], ['/beheer/instellingen#facturatie', 'file', 'Facturatie', 'Nummering, betaaltermijn en btw'], ['/beheer/instellingen#email', 'mail', 'E-mail', 'SMTP en afzender'], ['/beheer/medewerkers', 'shield', 'Medewerkers', 'Toegang voor je team'], ['/beheer/website/team', 'users', 'Team', 'Teamleden op Over ons'], ['/beheer/updates', 'refresh', 'Updates', 'GitHub-updater en migraties'], ['/beheer/website/paginas', 'layout', "Pagina's", 'Megamenu: cloud en ICT'], ['/beheer/website/blog', 'note', 'Blog', 'Berichten en nieuws'], ['/beheer/website/portfolio', 'image', 'Portfolio', 'Projecten en cases'], ['/beheer/website/logos', 'star', "Logo's", 'Logocarrousel per groep'], ['/beheer/website/tijdlijn', 'clock', 'Tijdlijn', 'Geschiedenis en overnames'], ['/beheer/website/datacenters', 'pin', 'Datacenters', 'Locaties op de kaart'], ['/beheer/demo-data', 'trash', 'Demo-data', 'Voorbeeldgegevens opruimen'], ['/beheer/koppelingen', 'link', 'Koppelingen', 'Realtime Register, Mollie, Cryptomus, Qevanto']], 'columns' => ['Bedrijf' => [0, 1, 2, 5, 6], 'Content' => [8, 9, 10, 11, 12, 13], 'Facturatie' => [3, 4], 'Systeem' => [7, 15, 14]], 'also' => ['/beheer/instellingen', '/beheer/website'], 'action' => ['/beheer/medewerkers/nieuw', 'Nieuwe medewerker']] : null,
]));
echo $partial('partials.panel', [
    'navSections' => $navSections, 'home' => '/beheer', 'profile' => '/beheer/medewerkers/' . \App\Core\Auth::id(), 'tagline' => 'Hosting facturatie',
    'footLinks' => [['/', 'globe', 'Bekijk website', true]], 'body' => $yield('content'),
]);
